-- 词法器分隔符洪水负值回归（C2）：
-- 修复前 Lexer::next 对空 token 位置的 ';' 逐个递归自调用，
-- 连续 N 个 ';' 即 N 层真实递归，约 10^5 个即栈溢出 SIGSEGV（--tcp 下远程可触发）。
-- 修复后改直返词元，解析器在第一个多余的 ';' 处即清晰报错退出非 0。
--
-- 用法：cat scripts/test/lex_semicolons.mt | ./build/mybot --robot=robots/test/lex_semicolons.sql
-- 期望退出码非 0，输出含 "Token ;"（在 CREATE 之外遇到 END 词元）
CREATE TABLE Timer (
	name   String,
	delay  String
);
INSERT INTO Timer (name, delay) VALUES ('t0', '10');

-- 下面是分号洪水：修复前逐个递归打爆栈，修复后应在第一个多余 ; 处报错
